const AudioSys={on:false,ensure(){},play(){},setOn(){},speak(text,btn){if(!("speechSynthesis" in window))return null;this.stopSpeak();const u=new SpeechSynthesisUtterance(text);u.lang="en-GB";u.rate=.95;if(btn){btn.classList.add("playing");u.onend=()=>btn.classList.remove("playing");u.onerror=()=>btn.classList.remove("playing");}speechSynthesis.speak(u);return u;},stopSpeak(){if("speechSynthesis" in window)speechSynthesis.cancel();$$?.(".play-btn.playing")?.forEach(b=>b.classList.remove("playing"));}};
