function save(){clearTimeout(saveT);saveT=setTimeout(()=>{if(!LMS.ok)return;try{const j=JSON.stringify(S);LMS.set("cmi.suspend_data",j);LMS.set("cmi.core.score.raw",Math.round(clamp(S.xp/MAX_XP*100,0,100)));LMS.set("cmi.core.lesson_status",S.finished?"completed":"incomplete");LMS.commit();}catch(e){}},250);}
function load(){if(!LMS.ok)return;try{const j=LMS.api.LMSGetValue("cmi.suspend_data");if(j){const p=JSON.parse(j);S=Object.assign(defaultState(),p);S.meters=Object.assign({eco:40,health:45,budget:500},p.meters||{});}}catch(e){}}
const lvl=()=>clamp(Math.floor(S.xp/320),0,LEVELS.length-1);
/* ================= UI HELPERS ================= */
function toast(msg,kind="info",ic){const t=document.createElement("div");t.className="toast"+(kind==="gold"?" gold":kind==="pen"?" pen":"");t.innerHTML=`<span>${icon(ic||(kind==="gold"?"trophy":kind==="pen"?"alert":"info"))}</span><span>${msg}</span>`;$("#toasts").appendChild(t);setTimeout(()=>{t.classList.add("out");setTimeout(()=>t.remove(),400);},3400);while($("#toasts").children.length>3)$("#toasts").firstChild.remove();}
function floatXP(ev,txt,neg=false){const s=document.createElement("span");s.className="float-xp"+(neg?" neg":"");s.textContent=txt;s.style.left=((ev&&ev.clientX)||innerWidth/2)+"px";s.style.top=(((ev&&ev.clientY)||300)-14)+"px";document.body.appendChild(s);setTimeout(()=>s.remove(),1000);}
function confetti(n=26){const cols=["#C8A24B","#E9CE7E","#1C6B4F","#7C2D3E","#B4632C","#2F6F8F"];for(let i=0;i<n;i++){const c=document.createElement("div");c.className="confetti";c.style.left=Math.random()*100+"vw";c.style.background=cols[i%cols.length];c.style.animationDuration=(1.7+Math.random()*1.6)+"s";c.style.animationDelay=(Math.random()*0.4)+"s";document.body.appendChild(c);setTimeout(()=>c.remove(),3600);}}
function addXP(n){S.xp=Math.max(0,S.xp+n);updateTopbar();save();}
function noteAnswer(ok,ev,amt=10){if(ok){S.correct++;S.streak++;S.bestStreak=Math.max(S.bestStreak,S.streak);floatXP(ev,`+${amt}`);AudioSys.play("ok");if(S.streak===5)earnAch("streak5");}
else{S.errors++;S.penalties++;S.streak=0;S.xp=Math.max(0,S.xp-PENALTY);floatXP(ev,`−${PENALTY} XP`,true);AudioSys.play("no");}
updateTopbar();save();}
function metersHTML(){const m=S.meters;return `<div class="meters"><div class="meter-row"><span>${icon("leaf")} Eco impact</span><div class="meter-track"><div class="meter-fill m-eco" style="width:${m.eco}%"></div></div><b>${m.eco}</b></div><div class="meter-row"><span>${icon("heart")} Student health</span><div class="meter-track"><div class="meter-fill m-health" style="width:${m.health}%"></div></div><b>${m.health}</b></div><div class="meter-row"><span>${icon("wallet")} Budget</span><div class="meter-track"><div class="meter-fill m-budget" style="width:${clamp(m.budget/8,0,100)}%"></div></div><b>£${m.budget}</b></div></div>`;}
function applyFx(fx){if(fx.eco)S.meters.eco=clamp(S.meters.eco+fx.eco,0,100);if(fx.health)S.meters.health=clamp(S.meters.health+fx.health,0,100);if(fx.budget)S.meters.budget=Math.max(0,S.meters.budget+fx.budget);save();}
function fxHTML(fx){const one=(v,l)=>v?`<span class="${v>0?"up":"down"}">${l} ${v>0?"+":""}${v}</span>`:`<span class="flat">${l} —</span>`;return `<div class="fx">${one(fx.eco,"Eco")}${one(fx.health,"Health")}${one(fx.budget,"£")}</div>`;}
