function earnAch(id){if(S.ach.includes(id))return;const a=ACH.find(x=>x.id===id);if(!a)return;S.ach.push(id);addXP(25);AudioSys.play("badge");toast(`Achievement unlocked: <b>${a.name}</b> +25 XP`,"gold",a.ic);confetti(14);save();updateTopbar();}
function awardBadge(i){const b=BADGES[i];if(S.badges.includes(b.id))return;S.badges.push(b.id);addXP(50);AudioSys.play("badge");confetti(30);save();}
function checkGuru(){const ids=["3b-gaps","3b-expert","3c-pro","3d-rel"];const rs=ids.map(i=>S.results[i]).filter(Boolean);if(rs.length===4){const p=rs.reduce((a,r)=>a+r.score,0)/rs.reduce((a,r)=>a+r.max,0);if(p>=0.8)earnAch("guru");}}
function checkRefMaster(){const ids=["g-det","g-ind","g-rel","g-write"];const rs=ids.map(i=>S.results[i]).filter(Boolean);if(rs.length===4){const p=rs.reduce((a,r)=>a+r.score,0)/rs.reduce((a,r)=>a+r.max,0);if(p>=0.8)earnAch("refmaster");}}
function completeTask(id,res,zone){if(S.results[id])return;S.results[id]={score:res.score,max:res.max,errors:res.errors,xp:res.xp,done:true};if(res.log)S.logs[id]=res.log;addXP(res.xp);AudioSys.play("pop");save();if(id==="3c-stat"&&res.score>=5)earnAch("ear");checkGuru();checkRefMaster();if(zone)zone.insertAdjacentHTML("beforeend",donePanelHTML(id));}
function donePanelHTML(id){const r=S.results[id];const pct=Math.round(r.score/r.max*100);const gIndex=S.route?.name==="grammar"?GRAMMAR.findIndex(x=>x.id===gramTopic):-1;const nextLabel=gIndex<0?"Continue":gIndex<GRAMMAR.length-1?"Next grammar topic":grammarReturnRoute?.name==="step"?"Return to mission step":"Return to previous page";return `<div class="done-panel"><div><div class="big">${pct>=80?"Excellent work!":pct>=50?"Task complete":"Keep practising!"}</div><div class="done-stats"><span>Score <b>${r.score}/${r.max}</b></span><span>Errors <b style="color:var(--danger)">${r.errors}</b></span><span>Penalty <b style="color:var(--danger)">−${r.errors*PENALTY} XP</b></span><span>Accuracy <b>${pct}%</b></span></div></div><div style="display:flex;gap:10px;align-items:center;margin-left:auto;flex-wrap:wrap"><button class="btn btn-ghost btn-sm" data-action="review" data-task="${id}">${icon("eye")} Review answers</button><span class="xp-gain">+${r.xp} XP</span></div></div><div class="footer-bar"><span class="muted small">Use the study prompts to revisit the source or language point.</span><button class="btn btn-gold" data-action="next-step">${nextLabel} ${icon("right")}</button></div>`;}
