function openReview(id){}
function openModal(html){$("#modalCard").innerHTML=html;$("#modal").classList.add("on");}
function closeModal(){$("#modal").classList.remove("on");}
/* ================= ENGINES ================= */
function scoreLine(zone,score,max,err){let el=$(".task-score",zone);if(!el){el=document.createElement("div");el.className="task-score";zone.prepend(el);}el.innerHTML=`<span>Answered</span><span class="ok">${icon("check")} ${score}</span><span class="err">${icon("x")} ${err} (−${err*PENALTY} XP)</span><span>of ${max}</span>`;}
function engMatch(zone,cfg){const t0=Date.now(),pairs=cfg.pairs,rights=shuffle(pairs.map((p,i)=>({d:p.d,i})));let sel=null,done=0,err=0,earned=0,log=[];
zone.innerHTML=`<p class="muted small" style="margin-bottom:12px">${cfg.hint||"Click a word, then its definition. Correct pairs lock in green."}</p><div class="match-grid"><div class="match-col" id="mL"></div><div class="match-col" id="mR"></div></div>`;
const L=$("#mL",zone),R=$("#mR",zone);pairs.forEach((p,i)=>L.insertAdjacentHTML("beforeend",`<button class="mterm" data-i="${i}">${p.icon?icon(p.icon):""}<span>${p.t}</span></button>`));rights.forEach(o=>R.insertAdjacentHTML("beforeend",`<button class="mdef" data-i="${o.i}"><span>${o.d}</span></button>`));scoreLine(zone,0,pairs.length,0);
L.addEventListener("click",e=>{const b=e.target.closest(".mterm");if(!b||b.classList.contains("done"))return;$$(".mterm.sel",L).forEach(x=>x.classList.remove("sel"));b.classList.add("sel");sel=+b.dataset.i;AudioSys.play("click");});
R.addEventListener("click",e=>{const b=e.target.closest(".mdef");if(!b||b.classList.contains("done"))return;if(sel==null){toast("Choose a word on the left first.","info");return;}const lt=$(`.mterm[data-i="${sel}"]`,L);
if(+b.dataset.i===sel){done++;earned+=10;noteAnswer(true,e,10);lt.classList.remove("sel");lt.classList.add("done");b.classList.add("done");lt.insertAdjacentHTML("afterbegin",`<span class="mnum">${done}</span>`);b.insertAdjacentHTML("afterbegin",`<span class="mnum">${done}</span>`);log.push({q:pairs[sel].t,user:pairs[sel].d,correct:pairs[sel].d,ok:true});sel=null;scoreLine(zone,done,pairs.length,err);
if(done===pairs.length){if(cfg.speedAch&&(Date.now()-t0)/1000<60)earnAch("speed");completeTask(cfg.id,{score:done,max:pairs.length,errors:err,xp:earned+(err===0?20:10),log},zone);}}
else{err++;noteAnswer(false,e);b.classList.add("shake");lt.classList.add("shake");log.push({q:pairs[sel].t,user:pairs[+b.dataset.i].d,correct:pairs[sel].d,ok:false});setTimeout(()=>{b.classList.remove("shake");lt.classList.remove("shake");},450);scoreLine(zone,done,pairs.length,err);}});}
function engMCQ(zone,cfg){const items=cfg.items.map(it=>({...it,shuffled:shuffle(it.opts.map((o,i)=>({o,ok:i===it.ans})))}));let answered=0,score=0,err=0,earned=0,log=[];
zone.innerHTML=items.map((it,qi)=>`<div class="qcard" data-q="${qi}"><div class="qtext"><span class="qnum">${qi+1}.</span>${it.q}</div><div class="opts">${it.shuffled.map((o,oi)=>`<button class="opt" data-o="${oi}"><span class="letter">${"ABCDE"[oi]}</span><span>${o.o}</span></button>`).join("")}</div></div>`).join("");scoreLine(zone,0,items.length,0);
zone.addEventListener("click",e=>{const b=e.target.closest(".opt");if(!b)return;const card=b.closest(".qcard");if(card.dataset.done)return;card.dataset.done="1";const qi=+card.dataset.q,it=items[qi],oi=+b.dataset.o,ch=it.shuffled[oi];$$(".opt",card).forEach(o=>{o.disabled=true;if(+o.dataset.o!==oi)o.classList.add("dim");});answered++;
if(ch.ok){score++;earned+=10;b.classList.add("right");$(".letter",b).innerHTML=icon("check");noteAnswer(true,e,10);}else{err++;b.classList.add("wrong");$(".letter",b).innerHTML=icon("x");noteAnswer(false,e);}
log.push({q:it.q,user:ch.o,correct:it.opts[it.ans],ok:ch.ok,expl:it.expl});scoreLine(zone,answered,items.length,err);if(answered===items.length)completeTask(cfg.id,{score,max:items.length,errors:err,xp:earned+(err===0?15:0),log},zone);});}
function engFadQuiz(zone,cfg){const items=cfg.items.map(it=>({...it,shuffled:shuffle(it.opts.map((o,i)=>({o,ok:i===it.ans})))}));let answered=0,score=0,err=0,earned=0,log=[];zone.innerHTML=items.map((it,qi)=>`<div class="qcard" data-q="${qi}"><div class="qtext"><span class="qnum">${qi+1}.</span>${it.q}</div><div class="opts">${it.shuffled.map((o,oi)=>`<button class="opt" data-o="${oi}"><span class="letter">${"ABCDE"[oi]}</span><span>${o.o}</span></button>`).join("")}</div><div class="fad-feedback" aria-live="polite"></div></div>`).join("");scoreLine(zone,0,items.length,0);zone.addEventListener("click",e=>{const b=e.target.closest(".opt");if(!b)return;const card=b.closest(".qcard");if(card.dataset.done)return;card.dataset.done="1";const qi=+card.dataset.q,it=items[qi],ch=it.shuffled[+b.dataset.o];$$('.opt',card).forEach(o=>{o.disabled=true;if(o===b)o.classList.add(ch.ok?"right":"wrong");else o.classList.add("dim");});answered++;const fb=$('.fad-feedback',card);if(ch.ok){score++;earned+=10;fb.className='fad-feedback feedback-hint';fb.textContent='Correct. Keep the passage as your evidence.';noteAnswer(true,e,10);}else{err++;fb.className='fad-feedback feedback-hint';fb.textContent='Not quite. '+it.expl;noteAnswer(false,e);}log.push({q:it.q,user:ch.o,ok:ch.ok,expl:it.expl});scoreLine(zone,answered,items.length,err);if(answered===items.length)completeTask(cfg.id,{score,max:items.length,errors:err,xp:earned+(err===0?15:0),log},zone);});}
function engGaps(zone,cfg){let answered=0,score=0,err=0,earned=0,log=[];zone.innerHTML=cfg.items.map((it,i)=>`<div class="qcard" data-q="${i}"><div class="gap-sentence">${it.pre}<span class="gap" id="gap-${cfg.id}-${i}">…</span>${it.post||""}</div><div class="chiprow">${shuffle(it.opts).map(o=>`<button class="chip" data-v="${esc(o)}">${o}</button>`).join("")}</div></div>`).join("");scoreLine(zone,0,cfg.items.length,0);
zone.addEventListener("click",e=>{const b=e.target.closest(".chip");if(!b)return;const card=b.closest(".qcard");if(card.dataset.done)return;card.dataset.done="1";const i=+card.dataset.q,it=cfg.items[i],v=b.dataset.v,ok=v===it.ans,g=$(`#gap-${cfg.id}-${i}`);g.textContent=v;g.classList.add(ok?"right":"wrong");$$(".chip",card).forEach(c=>c.disabled=true);b.classList.add(ok?"picked-good":"picked-bad");answered++;
if(ok){score++;earned+=10;noteAnswer(true,e,10);}else{err++;noteAnswer(false,e);}log.push({q:(it.pre+" ___ "+(it.post||"")).replace(/<[^>]+>/g,""),user:v,correct:it.ans,ok,expl:it.expl});scoreLine(zone,answered,cfg.items.length,err);if(answered===cfg.items.length)completeTask(cfg.id,{score,max:cfg.items.length,errors:err,xp:earned+(err===0?15:0),log},zone);});}
function engOrder(zone,cfg){let order=shuffle(cfg.items.map((t,i)=>i));if(order.every((v,i)=>v===i))order=order.reverse();let checked=false,err=0,log=[];
zone.innerHTML=`<p class="muted small" style="margin-bottom:12px">${cfg.hint}</p><div class="order-list" id="ordList"></div><div class="footer-bar"><button class="btn btn-ghost btn-sm" id="ordShuffle">${icon("refresh")} Shuffle again</button><button class="btn btn-gold" id="ordCheck">${icon("check")} Check the order</button></div>`;
const list=$("#ordList",zone);function draw(){list.innerHTML=order.map((idx,pos)=>`<div class="order-item" draggable="true" data-pos="${pos}"><span class="drag-handle">${icon("drag")}</span><span class="ord-num">${pos+1}</span><span>${cfg.items[idx]}</span><span class="ord-ctrl"><button class="ord-btn" data-mv="-1" data-pos="${pos}">${icon("up")}</button><button class="ord-btn" data-mv="1" data-pos="${pos}">${icon("down")}</button></span></div>`).join("");}draw();let dragPos=null;
list.addEventListener("dragstart",e=>{const it=e.target.closest(".order-item");if(!it||checked)return;dragPos=+it.dataset.pos;it.classList.add("dragging");});list.addEventListener("dragend",()=>$$(".order-item",list).forEach(x=>x.classList.remove("dragging","over")));list.addEventListener("dragover",e=>{e.preventDefault();const it=e.target.closest(".order-item");$$(".order-item.over",list).forEach(x=>x.classList.remove("over"));if(it)it.classList.add("over");});list.addEventListener("drop",e=>{e.preventDefault();const it=e.target.closest(".order-item");if(!it||dragPos==null||checked)return;const to=+it.dataset.pos;const[m]=order.splice(dragPos,1);order.splice(to,0,m);dragPos=null;AudioSys.play("click");draw();});
list.addEventListener("click",e=>{const b=e.target.closest(".ord-btn");if(!b||checked)return;const p=+b.dataset.pos,mv=+b.dataset.mv,np=p+mv;if(np<0||np>=order.length)return;[order[p],order[np]]=[order[np],order[p]];AudioSys.play("click");draw();});
$("#ordShuffle",zone).addEventListener("click",()=>{if(checked)return;order=shuffle(order);draw();});
$("#ordCheck",zone).addEventListener("click",e=>{if(checked)return;checked=true;let score=0;$$(".order-item",list).forEach((el,pos)=>{const ok=order[pos]===pos;el.classList.add(ok?"pos-ok":"pos-bad");if(ok)score++;else err++;log.push({q:`Position ${pos+1}`,user:cfg.items[order[pos]],correct:cfg.items[pos],ok});});$$(".ord-btn",list).forEach(b=>b.disabled=true);$("#ordShuffle",zone).disabled=true;$("#ordCheck",zone).disabled=true;noteAnswer(score===cfg.items.length,e,score*5);const xp=score*5+(score===cfg.items.length?20:0);completeTask(cfg.id,{score,max:cfg.items.length,errors:err,xp,log},zone);});}
function engMulti(zone,cfg){let picked=new Set(),done=false;zone.innerHTML=`<p class="muted small" style="margin-bottom:12px">${cfg.hint}</p><div class="opts" id="multiOpts">${cfg.opts.map((o,i)=>`<button class="opt" data-i="${i}"><span class="letter">${i+1}</span><span>${o.t}</span></button>`).join("")}</div><div class="footer-bar"><span class="muted small" id="multiCount">Choose exactly ${cfg.k}</span><button class="btn btn-gold" id="multiGo" disabled>${icon("check")} Confirm advice</button></div>`;const go=$("#multiGo",zone);
$("#multiOpts",zone).addEventListener("click",e=>{const b=e.target.closest(".opt");if(!b||done)return;const i=+b.dataset.i;if(picked.has(i)){picked.delete(i);b.classList.remove("right");$(".letter",b).textContent=i+1;}else{if(picked.size>=cfg.k){toast(`Only ${cfg.k} recommendations — deselect one first.`,"info");return;}picked.add(i);b.classList.add("right");$(".letter",b).innerHTML=icon("check");}AudioSys.play("click");$("#multiCount",zone).textContent=`${picked.size}/${cfg.k} selected`;go.disabled=picked.size!==cfg.k;});
go.addEventListener("click",e=>{if(done)return;done=true;let score=0,err=0,log=[];$$("#multiOpts .opt",zone).forEach(b=>{b.disabled=true;const i=+b.dataset.i,o=cfg.opts[i];if(picked.has(i)){if(o.good){score++;$(".letter",b).innerHTML=icon("check");}else{err++;b.classList.remove("right");b.classList.add("wrong");$(".letter",b).innerHTML=icon("x");}}else if(o.good)b.classList.add("dim");log.push({q:o.t,user:picked.has(i)?"recommended":"not recommended",correct:o.good?"good advice":"not good advice",ok:o.good===picked.has(i),expl:o.expl});});noteAnswer(err===0,e,score*15);AudioSys.play(err===0?"ok":"no");go.disabled=true;applyFx({health:score*5});completeTask(cfg.id,{score,max:cfg.k,errors:err,xp:score*15,log},zone);});}
function engDialogue(zone,cfg){let node=cfg.start,sum=0,best=0,log=[];zone.innerHTML=`<div class="chat-box" id="dChat"></div><div class="choices" id="dChoices"></div>`;const chat=$("#dChat",zone),ch=$("#dChoices",zone);
function bub(text,me){return `<div class="msg${me?" me":""}">${avatar(me?(cfg.me||"ben"):cfg.npc,40)}<div class="bub">${me?"":`<span class="who">${CHARS[cfg.npc].name}</span>`}${text}</div></div>`;}
function scroll(){chat.scrollTop=chat.scrollHeight;}
function show(){const n=cfg.nodes[node];ch.innerHTML="";chat.insertAdjacentHTML("beforeend",`<div class="typing" id="dTyping"><i></i><i></i><i></i></div>`);scroll();setTimeout(()=>{$("#dTyping",chat)?.remove();n.say.forEach(s=>chat.insertAdjacentHTML("beforeend",bub(s,false)));scroll();if(n.choices)ch.innerHTML=n.choices.map((c,i)=>`<button class="choice-btn" data-i="${i}">${c.t}</button>`).join("");else finish();},700);}
ch.addEventListener("click",e=>{const b=e.target.closest(".choice-btn");if(!b)return;const n=cfg.nodes[node],c=n.choices[+b.dataset.i];ch.innerHTML="";chat.insertAdjacentHTML("beforeend",bub(c.t,true));scroll();sum+=c.pts;const bestPts=Math.max(...n.choices.map(x=>x.pts));best+=bestPts;if(c.pts===bestPts&&c.pts>0)noteAnswer(true,e,c.pts);else if(c.pts===0)noteAnswer(false,e);else AudioSys.play("click");log.push({q:n.say[n.say.length-1],user:c.t,correct:n.choices.find(x=>x.pts===bestPts).t,ok:c.pts===bestPts,expl:c.note||""});node=c.next;setTimeout(show,450);});
function finish(){const err=log.filter(l=>!l.ok).length;if(cfg.id==="3c-invite"&&log.filter(l=>l.ok).length>=4)earnAch("social");if(cfg.phrases)chat.insertAdjacentHTML("beforeend",`<div class="phrase-card"><h4>${icon("chat")} Functional Language — keep this card!</h4>${cfg.phrases.map(p=>`<div style="margin-bottom:8px"><b class="small" style="color:var(--gold3)">${p.cat}</b><ul>${p.list.map(x=>`<li>${x}</li>`).join("")}</ul></div>`).join("")}</div>`);scroll();completeTask(cfg.id,{score:Math.round(sum/10),max:Math.round(best/10),errors:err,xp:sum+10,log},zone);}show();}
/* ================= LISTENING ================= */
const SPEAKERS=[
{id:"A",name:"Jake",col:"#2F6F8F",text:"Hi, I'm Jake. There's a vending machine at my school, and I use it all the time. If I forget my lunch, I just get a snack from the machine — crisps or a chocolate bar. I know it's junk food, but it's quick, and it's right next to the canteen. My friends use it too, especially before football practice.",keys:["school","junk food","snack"],decoys:["airport","Japan","charger"]},
{id:"B",name:"Mia",col:"#7C2D3E",text:"I'm Mia. Last February I visited my cousin in Japan, and I couldn't believe the vending machines there! You can buy almost anything — hot noodles, fresh eggs, and even umbrellas when it rains. A few machines sell clothes, like T-shirts in your size. I took hundreds of photos. I wanted to put one in my bedroom!",keys:["Japan","umbrellas","clothes"],decoys:["school","December","apples"]},
{id:"C",name:"Hannah",col:"#177E77",text:"My name's Hannah. In December I was at the airport, really early, and my phone was nearly dead. Then I remembered — some airports have machines with electronics. I bought a mobile phone charger from one, and it saved my life. Well, my holiday! Now I buy all my cables and headphones from machines.",keys:["airport","December","charger"],decoys:["umbrellas","healthy food","crisps"]},
{id:"D",name:"Dexter",col:"#1C6B4F",text:"Hello, I'm Dexter. People say vending machines are only for junk food, but ours is different. It sells healthy food — apples, bananas, salads and yoghurt. The machine can refrigerate fresh food, so the salads are safe to eat. I buy an apple every morning. If every school had one, we'd all eat better.",keys:["healthy food","apples","refrigerate"],decoys:["junk food","airport","clothes"]}];
function playerHTML(sp){return `<div class="spk-top"><span class="spk-av" style="background:${sp.col}">${sp.id}</span><div><b style="font-size:14px">${sp.name}</b><div class="small muted">Speaker ${sp.id}</div></div><button class="play-btn" data-spk="${sp.id}" style="margin-left:auto">${icon("play")} Listen</button></div>`;}
function bindPlayers(zone){zone.addEventListener("click",e=>{const p=e.target.closest(".play-btn");if(p){const sp=SPEAKERS.find(s=>s.id===p.dataset.spk);if(p.classList.contains("playing")){AudioSys.stopSpeak();return;}AudioSys.speak(sp.text,p);return;}const t=e.target.closest(".tr-toggle");if(t){const tr=$("#tr-"+t.dataset.spk,zone);tr.classList.toggle("open");t.textContent=tr.classList.contains("open")?"Hide transcript":"Can't hear it? Read transcript";}});}
/* ================= DECISIONS ================= */
function timerHTML(){const C=2*Math.PI*30;return `<div class="timer-wrap"><div class="timer-ring"><svg width="74" height="74"><circle cx="37" cy="37" r="30" stroke="#EDE4D0" stroke-width="7" fill="none"/><circle id="tRing" cx="37" cy="37" r="30" stroke="var(--warn)" stroke-width="7" fill="none" stroke-linecap="round" stroke-dasharray="${C}" stroke-dashoffset="0"/></svg><span class="tval" id="tVal">60</span></div><div><span class="urgent-tag">${icon("alert")} FORCE MAJEURE</span><p style="font-weight:700;font-size:13.5px;margin-top:8px">The supplier needs an answer <b>now</b>. Decide before the timer runs out! Timeout = extra −10 XP.</p></div></div>`;}
function buildDecision(zone,key,cfg){if(S.decisions[key]){const o=cfg.options.find(x=>x.id===S.decisions[key].id);zone.innerHTML=`<div class="outcome"><span class="tag">${icon("check")} Decision recorded</span><h3 style="margin:10px 0 6px">${o.title}</h3><p style="font-size:14px">${o.feedback}</p><div style="margin-top:12px">${fxHTML(o.fx)}</div></div><div class="footer-bar"><span></span><button class="btn btn-gold" data-action="next-step">Continue ${icon("right")}</button></div>`;return;}
zone.innerHTML=`${cfg.timer?timerHTML():""}<div class="problem-card"><b>${icon("alert")} ${cfg.urgent?"URGENT CASE FILE":"CASE FILE"}:</b> ${cfg.problem}</div><div class="dec-grid">${cfg.options.map(o=>`<button class="dec-card" data-id="${o.id}"><span class="dicon">${icon(o.icon)}</span><b>${o.title}</b><p>${o.desc}</p>${fxHTML(o.fx)}</button>`).join("")}</div>`;
let timeLeft=cfg.timer||0;if(cfg.timer){const ring=$("#tRing",zone),val=$("#tVal",zone),C=2*Math.PI*30;const tick=setInterval(()=>{timeLeft--;val.textContent=timeLeft;ring.style.strokeDashoffset=C*(1-timeLeft/cfg.timer);if(timeLeft<=10&&timeLeft>0)AudioSys.play("tick");if(timeLeft<=0){clearInterval(tick);if(!S.decisions[key])choose(cfg.timeout,true);}},1000);App.timers.push(tick);}
function choose(o,auto){if(S.decisions[key])return;S.decisions[key]={id:o.id,timeLeft};applyFx(o.fx);if(auto){S.xp=Math.max(0,S.xp-10);S.penalties+=2;toast("Time ran out! Extra penalty −10 XP","pen","alert");}else addXP(15);if(cfg.timer&&!auto&&timeLeft>=20)earnAch("cool");AudioSys.play(auto?"no":"pop");save();zone.innerHTML=`<div class="outcome"><span class="tag">${icon("check")} Decision recorded</span><h3 style="margin:10px 0 6px">${o.title}</h3><p style="font-size:14px">${o.feedback}</p>${auto?`<p class="small" style="color:var(--danger);margin-top:8px">Time ran out — this option was applied by default. −10 XP.</p>`:(cfg.timer?`<p class="small muted" style="margin-top:8px">Decided with ${timeLeft}s to spare.</p>`:"")}<div style="margin-top:12px">${fxHTML(o.fx)}</div></div><div class="footer-bar"><span class="muted small">+${auto?0:15} XP • Your choice shapes the final project.</span><button class="btn btn-gold" data-action="next-step">Continue ${icon("right")}</button></div>`;}
zone.addEventListener("click",e=>{const b=e.target.closest(".dec-card");if(!b)return;const o=cfg.options.find(x=>x.id===b.dataset.id);AudioSys.play("click");choose(o,false);});}
