function stepShell(tag,ic,title,sub){return `<div class="step-head"><span class="tag acc">${icon(ic)} ${tag}</span><h2>${title}</h2><div class="step-nav"><button class="icon-btn" data-action="prev-step" style="background:#fff;color:var(--ink);border-color:var(--goldLine)">${icon("left")}</button></div></div>${sub?`<p class="muted" style="margin:0 0 12px;font-size:13.5px">${sub}</p>`:""}<div class="penalty-hint">${icon("alert")} Correct +10 XP · Mistake −${PENALTY} XP</div>`;}
function taskCard(inner){return `<div class="card"><div class="task-zone">${inner||""}</div></div>`;}
function buildKeywords(zone){let doneCount=0,totalScore=0,totalErr=0,earned=0,log=[];zone.innerHTML=`<div class="spk-grid">${SPEAKERS.map(sp=>`<div class="spk-card" data-spk="${sp.id}">${playerHTML(sp)}<button class="link-btn tr-toggle" data-spk="${sp.id}">Can't hear it? Read transcript</button><div class="transcript" id="tr-${sp.id}">${sp.text}</div><div class="divider" style="margin:12px 0"></div><p class="small" style="font-weight:800;margin-bottom:8px">Tick the 3 key words you hear:</p><div class="chiprow kw-chips">${shuffle([...sp.keys,...sp.decoys]).map(k=>`<button class="chip" data-k="${esc(k)}">${k}</button>`).join("")}</div><button class="btn btn-ghost btn-sm kw-check" style="margin-top:11px" disabled>${icon("check")} Check (0/3)</button></div>`).join("")}</div>`;bindPlayers(zone);
zone.addEventListener("click",e=>{const chip=e.target.closest(".kw-chips .chip");if(chip){const card=chip.closest(".spk-card");if(card.dataset.done)return;chip.classList.toggle("sel");chip.style.borderColor=chip.classList.contains("sel")?"var(--gold)":"";chip.style.background=chip.classList.contains("sel")?"var(--goldSoft)":"";const n=$$(".chip.sel",card).length;const btn=$(".kw-check",card);btn.disabled=n!==3;btn.innerHTML=`${icon("check")} Check (${n}/3)`;AudioSys.play("click");return;}
const chk=e.target.closest(".kw-check");if(chk){const card=chk.closest(".spk-card");if(card.dataset.done)return;card.dataset.done="1";const sp=SPEAKERS.find(s=>s.id===card.dataset.spk);let sc=0;$$(".kw-chips .chip",card).forEach(c=>{c.disabled=true;const isKey=sp.keys.includes(c.dataset.k),sel=c.classList.contains("sel");c.style.borderColor="";c.style.background="";if(sel&&isKey){c.classList.add("picked-good");sc++;}else if(sel&&!isKey)c.classList.add("picked-bad");else if(!sel&&isKey)c.style.borderColor="var(--warn)";});chk.disabled=true;chk.innerHTML=`${icon("check")} ${sc}/3 correct`;totalScore+=sc;totalErr+=3-sc;earned+=sc*2;noteAnswer(sc===3,e,sc*2);log.push({q:`Speaker ${sp.id} — key words`,user:[...$$(".chip.picked-good,.chip.picked-bad",card)].map(c=>c.dataset.k).join(", "),correct:sp.keys.join(", "),ok:sc===3});doneCount++;if(doneCount===4)completeTask("3c-keys",{score:totalScore,max:12,errors:totalErr,xp:earned+(totalErr===0?15:0),log},zone);}});}
function buildSurvey(zone){let i=0,score=0,err=0,earned=0,log=[];zone.innerHTML=`<div class="chat-box" id="svChat"></div><div id="svCtl" style="margin-top:14px"></div>`;const chat=$("#svChat",zone),ctl=$("#svCtl",zone);
function addMsg(who,text,me){chat.insertAdjacentHTML("beforeend",`<div class="msg${me?" me":""}">${avatar(me?"ben":who,40)}<div class="bub">${me?"":`<span class="who">${CHARS[who].name}</span>`}${text}</div></div>`);chat.scrollTop=chat.scrollHeight;}
function step(){if(i>=SURVEY3B.length){completeTask("3b-survey",{score,max:8,errors:err,xp:earned+(err===0?15:0),log},zone);return;}const s=SURVEY3B[i];ctl.innerHTML=`<div class="qcard"><div class="qtext"><span class="qnum">Q${i+1}.</span>Ask ${CHARS[s.who].name.split(",")[0]}: <span class="gap" id="svGap">…</span>${s.qpost}</div><div class="chiprow">${s.qopts.map(o=>`<button class="chip" data-v="${o}">${o}</button>`).join("")}</div></div>`;$$(".chip",ctl).forEach(c=>c.addEventListener("click",e=>{const v=c.dataset.v,ok=v===s.qans;$("#svGap",ctl).textContent=v;$("#svGap",ctl).classList.add(ok?"right":"wrong");$$(".chip",ctl).forEach(x=>x.disabled=true);c.classList.add(ok?"picked-good":"picked-bad");if(ok){score++;earned+=5;noteAnswer(true,e,5);}else{err++;noteAnswer(false,e);}log.push({q:"___"+s.qpost,user:v,correct:s.qans,ok});addMsg("ben",v+s.qpost,true);setTimeout(()=>{addMsg(s.who,s.reply,false);report(s);},650);}));}
function report(s){ctl.innerHTML=`<div class="qcard soft"><div class="qtext">${icon("note")} ${s.rlabel}</div><div class="chiprow">${shuffle(s.ropts).map(o=>`<button class="chip" data-v="${esc(o)}">${o}</button>`).join("")}</div></div>`;$$(".chip",ctl).forEach(c=>c.addEventListener("click",e=>{const v=c.dataset.v,ok=v===s.rans;$$(".chip",ctl).forEach(x=>x.disabled=true);c.classList.add(ok?"picked-good":"picked-bad");if(ok){score++;earned+=5;noteAnswer(true,e,5);}else{err++;noteAnswer(false,e);}log.push({q:s.rlabel,user:v,correct:s.rans,ok});i++;setTimeout(step,500);}));}step();}
function buildShop(zone){const BUD=25;let cart=new Set(),checked=false;zone.innerHTML=`<div class="shop-layout"><div><div class="shop-grid" id="shopGrid">${SHOP_ITEMS.map(it=>`<div class="shop-item" data-id="${it.id}">${imgHTML(it.img,it.n,"","leaf")}<b>${it.n}</b><div class="shop-tags"><span class="stag ${it.h>0?"h":"bad"}">${icon("heart")}</span><span class="stag ${it.e>0?"e":"bad"}">${icon("leaf")}</span>${it.pr?`<span class="stag p">${icon("bolt")}</span>`:""}</div><div class="price">£${it.p.toFixed(2)}</div><button class="btn btn-ghost btn-sm add-btn">${icon("cart")} Add</button></div>`).join("")}</div></div><div class="card soft trolley"><b style="display:flex;gap:8px;align-items:center">${icon("cart")} Your trolley</b><div class="budget-bar"><div class="budget-fill" id="budFill" style="width:0%"></div></div><div class="small" style="font-weight:800" id="budTxt">£0.00 / £25.00</div><div class="trolley-list" id="troList"><span class="muted small">Empty — add items.</span></div><div class="divider" style="margin:12px 0"></div><b class="small">Constraints</b><div id="conList"></div><button class="btn btn-gold" id="checkout" style="width:100%;margin-top:12px">${icon("check")} Checkout</button></div></div>`;
const cons=()=>{const items=[...cart].map(id=>SHOP_ITEMS.find(x=>x.id===id));const spent=items.reduce((a,x)=>a+x.p,0);return[{t:`Within £25 (now £${spent.toFixed(2)})`,ok:spent<=BUD&&items.length>0},{t:`4+ healthy items (${items.filter(x=>x.h>0).length})`,ok:items.filter(x=>x.h>0).length>=4},{t:`1+ protein (${items.filter(x=>x.pr).length})`,ok:items.filter(x=>x.pr).length>=1},{t:`Max 2 junk items (${items.filter(x=>x.h<0).length})`,ok:items.filter(x=>x.h<0).length<=2},{t:`3+ eco items (${items.filter(x=>x.e>0).length})`,ok:items.filter(x=>x.e>0).length>=3}];};
function draw(){const items=[...cart].map(id=>SHOP_ITEMS.find(x=>x.id===id));const spent=items.reduce((a,x)=>a+x.p,0);$("#budFill",zone).style.width=clamp(spent/BUD*100,0,100)+"%";$("#budFill",zone).classList.toggle("over",spent>BUD);$("#budTxt",zone).textContent=`£${spent.toFixed(2)} / £25.00`;$("#troList",zone).innerHTML=items.length?items.map(x=>`<div class="trolley-row"><span>${x.n}</span><span style="display:flex;gap:8px;align-items:center"><b>£${x.p.toFixed(2)}</b>${checked?"":`<button data-rm="${x.id}">${icon("x")}</button>`}</span></div>`).join(""):`<span class="muted small">Empty — add items.</span>`;$("#conList",zone).innerHTML=cons().map(c=>`<div class="constraint${c.ok?" met":""}">${icon(c.ok?"check":"x")} ${c.t}</div>`).join("");$$(".shop-item",zone).forEach(el=>{const inC=cart.has(el.dataset.id);el.classList.toggle("in",inC);$(".add-btn",el).innerHTML=inC?`${icon("check")} In trolley`:`${icon("cart")} Add`;$(".add-btn",el).disabled=checked;});}draw();
zone.addEventListener("click",e=>{if(checked)return;const add=e.target.closest(".add-btn");if(add){const id=add.closest(".shop-item").dataset.id;cart.has(id)?cart.delete(id):cart.add(id);AudioSys.play("click");draw();return;}const rm=e.target.closest("[data-rm]");if(rm){cart.delete(rm.dataset.rm);AudioSys.play("click");draw();}});
$("#checkout",zone).addEventListener("click",e=>{if(checked)return;if(cart.size===0){toast("Add some items first!","info");return;}checked=true;const cs=cons(),met=cs.filter(c=>c.ok).length,items=[...cart].map(id=>SHOP_ITEMS.find(x=>x.id===id));const spent=items.reduce((a,x)=>a+x.p,0);if(met===5)earnAch("budget");applyFx({eco:met>=4?10:met*2,health:items.filter(x=>x.h>0).length*2,budget:-Math.round(spent)});const log=cs.map(c=>({q:c.t,user:c.ok?"met":"not met",correct:"met",ok:c.ok}));S.trolley={items:[...cart],spent,met};noteAnswer(met===5,e,met*10);draw();$("#checkout",zone).disabled=true;$("#checkout",zone).insertAdjacentHTML("afterend",`<div class="qcard" style="margin-top:12px"><div class="qtext">${icon("spark")} Cooking Race bonus: name your canteen menu!</div><div class="field"><input id="menuName" maxlength="48" placeholder="e.g. The Green Power Lunch"></div><button class="btn btn-ghost btn-sm" id="menuSave">${icon("check")} Save menu (+5 XP)</button></div>`);$("#menuSave",zone).addEventListener("click",()=>{const v=$("#menuName",zone).value.trim();if(!v){toast("Give your menu a name!","info");return;}S.menu=v;addXP(5);AudioSys.play("pop");$("#menuSave",zone).disabled=true;$("#menuName",zone).disabled=true;toast(`Menu saved: <b>${esc(v)}</b>`,"info","spark");save();});completeTask("3d-shop",{score:met,max:5,errors:5-met,xp:met*10+(met===5?15:0),log},zone);});}
function buildNote(zone){let picks={};zone.innerHTML=`<div class="build-grid"><div>${NOTE_SLOTS.map(s=>`<div class="slot"><label>${s.label}</label><div class="chiprow" data-slot="${s.key}">${shuffle(s.opts).map(o=>`<button class="chip" data-t="${esc(o.t)}" style="border-radius:12px;text-align:left">${o.t}</button>`).join("")}</div></div>`).join("")}<button class="btn btn-gold" id="noteGo" disabled>${icon("note")} Leave the note</button></div><div><label class="small" style="font-weight:900;text-transform:uppercase;letter-spacing:1px;color:var(--gold3)">Live preview</label><div class="note-preview" id="notePrev" style="margin-top:10px"><b>Ben</b><br><span class="muted">Choose the parts of your note…</span></div><div class="gnote" style="margin-top:16px">${icon("bulb")}<span><b>Writing guide:</b> name at the top, no greeting. Short sentences + ellipsis. Abbreviations welcome!</span></div></div></div>`;
function preview(){const parts=NOTE_SLOTS.map(s=>picks[s.key]).filter(Boolean);$("#notePrev",zone).innerHTML=`<b>Ben</b><br>`+(parts.length?parts.join("<br>"):`<span class="muted">Choose the parts of your note…</span>`)+`<br><b>${esc(S.name||"Your consultant")}</b>`;$("#noteGo",zone).disabled=Object.keys(picks).length<4;}
zone.addEventListener("click",e=>{const c=e.target.closest(".chiprow[data-slot] .chip");if(!c||zone.dataset.done)return;const slot=c.closest(".chiprow").dataset.slot;$$(".chip",c.closest(".chiprow")).forEach(x=>x.classList.remove("picked-good"));c.classList.add("picked-good");picks[slot]=c.dataset.t;AudioSys.play("click");preview();});
$("#noteGo",zone).addEventListener("click",e=>{if(zone.dataset.done)return;zone.dataset.done="1";let score=0,err=0,log=[],abbr=false;NOTE_SLOTS.forEach(s=>{const o=s.opts.find(x=>x.t===picks[s.key]);const ok=o.pts===10;if(ok)score++;else err++;if(o.abbr)abbr=true;log.push({q:s.label,user:picks[s.key],correct:s.opts.find(x=>x.pts===10).t,ok,expl:o.why||""});});$$(".chip",zone).forEach(c=>c.disabled=true);$("#noteGo",zone).disabled=true;noteAnswer(err===0,e,score*10);completeTask("3e-note",{score,max:4,errors:err,xp:score*10+(abbr?5:0)+(err===0?10:0),log},zone);});}
const POSTER_FIELDS=[{key:"title",label:"Event title",opts:["","GREEN CANTEEN LAUNCH!","Healthy Food Week","Canteen Meeting"],req:"GREEN CANTEEN LAUNCH!"},{key:"date",label:"Date",opts:["","Mon 16 June","Fri 13 June","Sometime soon"],req:"Mon 16 June"},{key:"time",label:"Time",opts:["","3.30 p.m.","In the morning","Whenever"],req:"3.30 p.m."},{key:"place",label:"Place",opts:["","School hall","The canteen","Online"],req:"School hall"},{key:"purpose",label:"Why? (raise money for…)",opts:["","a new recycling station","a teachers' coffee machine","no reason — just fun"],req:"a new recycling station"}];
function buildPoster(zone){const cfg=S.poster||{title:"",date:"",time:"",place:"",purpose:"",contact:"",rsvp:true,fyi:false,pal:0};zone.innerHTML=`<div class="build-grid"><div>${POSTER_FIELDS.map(f=>`<div class="field"><label>${f.label} *</label><select data-f="${f.key}">${f.opts.map(o=>`<option value="${esc(o)}"${o===cfg[f.key]?" selected":""}>${o||"— choose —"}</option>`).join("")}</select></div>`).join("")}<div class="field"><label>Contact details *</label><input data-f="contact" maxlength="40" placeholder="e.g. Tel: 07700 900123 • Rm 12" value="${esc(cfg.contact)}"></div><div class="toggle-row"><button class="tgl${cfg.rsvp?" on":""}" data-t="rsvp"></button> Add “RSVP asap” line (+5)</div><div class="toggle-row"><button class="tgl${cfg.fyi?" on":""}" data-t="fyi"></button> Add FYI: free healthy snacks (+5)</div><div class="field" style="margin-top:12px"><label>Poster palette</label><div class="palette-row">${[0,1,2].map(p=>`<button class="pal p${p}${cfg.pal===p?" sel":""}" data-p="${p}"></button>`).join("")}</div></div><div class="check-list" id="pCheck"></div><button class="btn btn-gold" id="posterGo" style="margin-top:14px" disabled>${icon("poster")} Publish announcement</button></div><div><label class="small" style="font-weight:900;text-transform:uppercase;letter-spacing:1px;color:var(--gold3)">Live preview</label><div id="posterPrev" style="margin-top:10px"></div></div></div>`;
function posterHTML(c){return `<div class="poster p${c.pal}"><h3>${esc(c.title||"YOUR EVENT TITLE")}</h3><div class="p-row">${icon("timer")} ${esc(c.date||"Date?")} • ${esc(c.time||"Time?")}</div><div class="p-row">${icon("flag")} ${esc(c.place||"Place?")}</div><div class="p-purpose">${icon("heart")} We are raising money for <b>${esc(c.purpose||"…")}</b>. Come and try the new healthy menu — everyone's invited!</div>${c.fyi?`<div class="p-row" style="margin-top:9px">${icon("spark")} FYI: free healthy snacks for the first 50 guests!</div>`:""}<div class="p-foot">${esc(c.contact||"Contact: ?")}${c.rsvp?" • RSVP asap":""}</div></div>`;}
function valid(){const reqOk=POSTER_FIELDS.every(f=>cfg[f.key]===f.req);const conOk=cfg.contact.trim().length>=6;$("#pCheck",zone).innerHTML=[...POSTER_FIELDS.map(f=>({t:f.label,ok:cfg[f.key]===f.req})),{t:"Contact details",ok:conOk}].map(c=>`<div class="constraint${c.ok?" met":""}">${icon(c.ok?"check":"x")} ${c.t}</div>`).join("");$("#posterGo",zone).disabled=!(reqOk&&conOk);return reqOk&&conOk;}
function draw(){$("#posterPrev",zone).innerHTML=posterHTML(cfg);valid();}draw();
zone.addEventListener("change",e=>{const f=e.target.dataset.f;if(f){cfg[f]=e.target.value;AudioSys.play("click");draw();}});zone.addEventListener("input",e=>{const f=e.target.dataset.f;if(f){cfg[f]=e.target.value;draw();}});
zone.addEventListener("click",e=>{const t=e.target.closest(".tgl");if(t&&!zone.dataset.done){const k=t.dataset.t;cfg[k]=!cfg[k];t.classList.toggle("on",cfg[k]);AudioSys.play("click");draw();return;}const p=e.target.closest(".pal");if(p&&!zone.dataset.done){cfg.pal=+p.dataset.p;$$(".pal",zone).forEach(x=>x.classList.toggle("sel",+x.dataset.p===cfg.pal));AudioSys.play("click");draw();}});
$("#posterGo",zone).addEventListener("click",e=>{if(zone.dataset.done||!valid())return;zone.dataset.done="1";S.poster={...cfg};applyFx({eco:5,health:5,budget:100});const bonus=(cfg.rsvp?5:0)+(cfg.fyi?5:0);const log=[{q:"Announcement checklist",user:"All 6 required elements + design",correct:"what, when, where, why, contact",ok:true,expl:"Charity purpose chosen correctly — +£100 raised."}];$$("select,input,.tgl,.pal",zone).forEach(x=>x.disabled=true);$("#posterGo",zone).disabled=true;noteAnswer(true,e,60);AudioSys.play("badge");completeTask("3e-poster",{score:6,max:6,errors:0,xp:60+bonus,log},zone);});}
