function renderAchievements(el){const acc=(S.correct+S.errors)?Math.round(S.correct/(S.correct+S.errors)*100):100;const nextLvl=320-(S.xp%320);
el.innerHTML=`<div class="photo-hero" style="min-height:230px">${imgHTML("ach","Team achievements","", "trophy",false)}<div class="veil"></div><div class="ph-content"><div class="kicker">Progress</div><h1>Achievements</h1><p style="max-width:640px;color:#D9E4DC;font-size:14px">Your consultant profile: XP, levels, mission badges, special achievements and penalty statistics.</p><div class="hero-meta"><span>${icon("trophy")} ${S.badges.length}/6 badges</span><span>${icon("star")} ${S.ach.length}/${ACH.length} achievements</span><span>${icon("flame")} Best streak ${S.bestStreak}</span></div></div></div>
<div class="card" style="margin-top:20px"><div style="display:flex;gap:16px;align-items:center;flex-wrap:wrap">${avatar("ben",64)}<div><b style="font-size:18px">${esc(S.name||"Consultant")}</b><div class="muted small">${LEVELS[lvl()]} • Level ${lvl()+1}</div><div class="meter-track" style="width:240px;margin-top:8px"><div class="meter-fill m-budget" style="width:${(S.xp%320)/3.2}%"></div></div><div class="small muted" style="margin-top:4px">${nextLvl} XP to next level</div></div><div class="xp-gain" style="margin-left:auto">${S.xp} XP</div></div></div>
<div class="stat-grid" style="margin-top:16px"><div class="stat-box"><b>${S.correct}</b><span>Correct</span></div><div class="stat-box danger"><b>${S.errors}</b><span>Mistakes</span></div><div class="stat-box danger"><b>−${S.penalties*PENALTY}</b><span>Penalty XP</span></div><div class="stat-box"><b>${acc}%</b><span>Accuracy</span></div><div class="stat-box"><b>${S.bestStreak}</b><span>Best streak</span></div><div class="stat-box"><b>${S.vocabKnown}</b><span>Words known</span></div></div>
<div class="card" style="margin-top:16px"><b style="display:flex;gap:8px;align-items:center;margin-bottom:14px">${icon("target")} Case dashboard</b>${metersHTML()}</div>
<div class="card" style="margin-top:16px"><span class="tag">${icon("medal")} Mission badges</span><div class="badge-grid" style="margin-top:16px">${BADGES.map(b=>`<div class="bslot${S.badges.includes(b.id)?" earned":""}"><div class="bmed">${medalSVG(b.c1,b.c2,b.ic,62,S.badges.includes(b.id))}</div>${b.name}</div>`).join("")}</div></div>
<div class="card" style="margin-top:16px"><span class="tag">${icon("star")} Special achievements</span><div style="margin-top:16px">${ACH.map(a=>`<div class="ach-row${S.ach.includes(a.id)?" earned":""}"><span class="aic">${icon(a.ic)}</span><div><b>${a.name}</b><span class="small muted">${a.desc}</span></div>${S.ach.includes(a.id)?`<span style="margin-left:auto;color:var(--ok)">${icon("check")}</span>`:`<span class="small muted" style="margin-left:auto">+25 XP</span>`}</div>`).join("")}</div></div>`;}
