AudioSys.ensure=function(){if(!this.ctx){const C=window.AudioContext||window.webkitAudioContext;if(C)this.ctx=new C();}if(this.ctx&&this.ctx.state==="suspended")this.ctx.resume().catch(()=>{});};
AudioSys.setOn=function(v){this.on=!!v;if(typeof S!=="undefined"){S.sound=this.on;save();}updateSoundBtns();};
AudioSys.play=function(kind="click"){if(!this.on)return;this.ensure();if(!this.ctx)return;const n=kind==="no"?[330,220]:kind==="ok"?[660,880]:kind==="badge"?[523,659,784]:[520],t=this.ctx.currentTime;n.forEach((f,i)=>{const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type="sine";o.frequency.setValueAtTime(f,t+i*.075);g.gain.setValueAtTime(.0001,t+i*.075);g.gain.exponentialRampToValueAtTime(kind==="no"?.045:.035,t+i*.075+.012);g.gain.exponentialRampToValueAtTime(.0001,t+i*.075+.09);o.connect(g);g.connect(this.ctx.destination);o.start(t+i*.075);o.stop(t+i*.075+.1);});};
document.addEventListener("pointerdown",()=>AudioSys.ensure(),{once:true});

