function studyFocusV10(id){if(String(id).includes("fad"))return "Re-read the named Fad Diets passage. Separate the diet’s claim from the writer’s evaluation and reported evidence.";if(String(id).includes("3a"))return "Revisit environmental vocabulary and the reading detail that supports your choice.";if(String(id).includes("3b"))return "Review countable and uncountable nouns, quantifiers and the client evidence.";if(String(id).includes("3c"))return "Replay the relevant audio and review key words or the functional-language pattern.";if(String(id).includes("3d"))return "Revisit the reading detail, container vocabulary and relative-clause rule.";if(String(id).includes("3e"))return "Review the purpose, short-text conventions and required message elements.";return "Re-read the relevant text, vocabulary set or grammar note. Use the evidence that supports your choice.";}
const FAD_COACH_PROMPTS_V11=["Re-read the opening lines of the second diet. Look for another name used for it.","Look back at the first paragraph of the Cabbage Soup Diet section and check its list of extra ingredients.","In the first ‘Does it work?’ paragraph, find the sentence about what the diet lacks.","Revisit the Master Cleanse section and find the reason the text gives for weight loss.","Read the final part of the Master Cleanse section. Compare the claim with what dieticians say.","Re-read the opening sentence of the Blood Group Diet section. Identify what the diet is based on.","Check the last sentence in the Blood Group Diet section for the researchers’ finding.","Revisit the final paragraph. Compare both parts of the article conclusion."];
function coachPromptV11(ev){const card=ev?.target?.closest?.(".qcard"),q=Number(card?.dataset.q||0),route=S.route||{},task=route.name==="step"?(LESSONS[route.l]?.steps[route.s]?.task||""):"";if(task.includes("fad")||ev?.target?.closest?.("#a-fad"))return FAD_COACH_PROMPTS_V11[q]||"Re-read the conclusion and separate the claim from the evidence.";if(task.startsWith("3a"))return "Revisit the reading about packaging, food waste, food miles and resource use.";if(task.startsWith("3b"))return "Re-read the relevant client or diet passage, then check the quantifier rule on this screen.";if(task.startsWith("3c"))return "Replay the relevant recording and review the key words or functional-language pattern.";if(task.startsWith("3d"))return "Return to the extract and check the detail that supports your choice.";if(task.startsWith("3e"))return "Review the audience, purpose and required details before trying again.";return "Look back at the related text, vocabulary or grammar rule and compare it with the evidence.";}
