/* v13 additions: practical grammar, Skills Test Unit 3, structured teacher notes and final analytics. */
const GRAMMAR_REAL_LIFE_V13={
det:{title:"Quantities in a real food order",text:"At a café, supermarket or when planning a recipe, countable and uncountable nouns help you ask for the right amount and avoid waste. Use a few for separate items, a little for an amount, and choose much or many by the noun.",items:[
{q:"You are planning a picnic. Which request is natural?",opts:["Could we buy a few apples?","Could we buy a little apples?"],ans:0,expl:"Check whether the noun names separate items or an amount."},
{q:"A recipe needs oil. Which note is clear?",opts:["Add a few olive oil.","Add a little olive oil."],ans:1,expl:"Check whether oil is counted as separate units here."},
{q:"You are checking a café order. Which question fits coffee?",opts:["How many coffee do we need?","How much coffee do we need?"],ans:1,expl:"Check the noun type before choosing the quantity question."}]},
ind:{title:"Unknown people, things and places",text:"Use indefinite pronouns when arranging a meal or solving a delivery problem and the person, item or place is not yet known. After everyone, someone and nobody, use a singular verb; avoid two negatives in one clause.",items:[
{q:"A delivery arrives, but the label has no name. What would you ask?",opts:["Did anyone order this?","Did no one order this?"],ans:0,expl:"Check how English forms a neutral question about an unknown person."},
{q:"You checked the kitchen and found zero plates. Which report is standard?",opts:["There isn't nothing in the cupboard.","There is nothing in the cupboard."],ans:1,expl:"Check the one-negative rule and the verb form."},
{q:"You are writing a team message. Which sentence agrees correctly?",opts:["Everyone bring a reusable bottle.","Everyone brings a reusable bottle."],ans:1,expl:"Check whether an indefinite pronoun takes a singular or plural verb."}]},
rel:{title:"Adding useful detail",text:"Relative clauses make practical messages more precise: identify the supplier, ingredient, restaurant or delivery time without writing several short sentences. Use the noun before the gap to decide whether it refers to a person, thing, place, time or owner.",items:[
{q:"You are recommending a market. Complete: This is the market ___ sells local vegetables.",opts:["where","that"],ans:1,expl:"Look at the role of the missing word in the clause that follows."},
{q:"You are describing a supplier. Complete: We chose a farm ___ produce is in season.",opts:["whose","who"],ans:0,expl:"Check whether the sentence shows ownership or names a person."},
{q:"You are arranging collection. Complete: Friday is the day ___ the order arrives.",opts:["when","which"],ans:0,expl:"Check whether the noun before the gap is a time."}]},
write:{title:"Short messages people can act on",text:"Notes and announcements are useful for a real event: a team meal, menu launch or food collection. Ellipsis and abbreviations save space, but the reader still needs the purpose, key details and a clear next action.",items:[
{q:"A short team note must ask colleagues to reply. Which abbreviation serves that purpose?",opts:["RSVP","FYI"],ans:0,expl:"Check which abbreviation asks the reader to respond."},
{q:"You are posting an example menu item. Which marker introduces an example?",opts:["e.g.","etc."],ans:0,expl:"Check which short form introduces an example rather than an unfinished list."},
{q:"Which note gives a clear action in concise informal style?",opts:["Team lunch Friday, 1 pm. Bring a reusable cup. Reply asap.","I am writing to inform everybody that a lunch event shall occur."],ans:0,expl:"Check whether the message is concise and tells the reader what to do."}]}
};
GRAMMAR.forEach(function(g){
var p=GRAMMAR_REAL_LIFE_V13[g.id];
g.html+='<section class="real-life-grammar"><span class="tag acc">Use it in real life</span><h3>'+p.title+'</h3><p>'+p.text+'</p><div class="example-box"><b>Mini challenge</b><br>Choose the wording that would help in a real food order, team message or event notice. Then explain the clue you used.</div></section>';
g.quiz=g.quiz.concat(p.items);
});
