var prompts={det:"Return to Countable vs Uncountable. Identify whether the noun names separate items or an amount, then check which quantifier pattern the sentence needs.",ind:"Review the some-, any-, no- and every- patterns. Check the sentence type and whether the indefinite pronoun takes a singular verb.",rel:"Return to the relative-clause table. Identify the noun before the gap and decide what role the missing word has in the clause.",write:"Check the abbreviation or note-writing rule. Ask what the reader needs to do and whether the short form fits that purpose."};
return prompts[gramTopic]||"Revisit the grammar rule and check the role of the missing word in this sentence.";
